func _goto_sector()->void:
	if model!=null and not model.native:status.text="Исходная галактическая карта доступна в новом полёте.";return
	if not sector_x.text.is_valid_int() or not sector_y.text.is_valid_int():status.text="Координаты сектора должны быть целыми.";return
	# Validate before narrowing to Vector2i; an oversized text integer must not
	# wrap through32bits back into a valid sector.
	var x:=int(sector_x.text);var y:=int(sector_y.text)
	if x< -5912 or x>2279 or y< -5412 or y>2779:status.text="Такой сектор находится за границей галактики.";return
	var raw:=Model.raw_sector(Vector2i(x,y))
	if not Model.valid_sector(raw):status.text="Такой сектор находится за границей галактики.";return
	_center=Vector2(raw)+Vector2(0.5,0.5);_overview=false;_request_now()

func release_pointers()->void:
	_pointers.clear();_pinch_distance=0;_mouse_rotating=false
	for b in buttons.values():b.release_pointer()
	if results!=null:
		for b in results.get_children():
			if b.has_method("release_pointer"):b.release_pointer()
func _inside_plot(global:Vector2)->bool:return _plot.has_point(get_global_transform_with_canvas().affine_inverse()*global)
func _local(global:Vector2)->Vector2:return get_global_transform_with_canvas().affine_inverse()*global
func _pan(delta:Vector2)->void:
	if model==null or not delta.is_finite():return
	if _overview:
		_center=Model.clamp_center(_center+Vector2(-delta.x,delta.y)*Vector2(320,158)/_overview_rect.size*float(_overview_scale))
	else:_center=Model.clamp_center(_center-Model.pan_delta(delta,_yaw,_tilt,_pixels_per_ly))
	_request_dirty=true;_request_clock=0;queue_redraw()
func _tap(point:Vector2)->void:
	if model==null or loading():return
	if _overview:
		if _overview_rect.has_point(point):_center=model.overview_sector((point-_overview_rect.position)/_overview_rect.size*Vector2(320,158),_overview_scale);_overview=false;_request_now()
		return
	var best:=-1;var distance:=24.0
	for row:Dictionary in _markers:
		var d:float=point.distance_to(row.point)
		if d<distance:distance=d;best=int(row.id)
	if best>=0:select_system(best)
func _input(event:InputEvent)->void:
	if not input_allowed or not is_visible_in_tree():release_pointers();return
	if event is InputEventScreenTouch:
		if event.canceled:
			_pointers.erase(event.index);_pinch_distance=0;return
		if event.pressed:
			if not _inside_plot(event.position):return
			_pointers[event.index]=_local(event.position)
			if _pointers.size()==1:_press_origin=_local(event.position);_last_pointer=_press_origin;_dragged=false
			if _pointers.size()==2:
				var p:Array=_pointers.values();_pinch_distance=p[0].distance_to(p[1]);_pinch_angle=(p[1]-p[0]).angle();_dragged=true
			get_viewport().set_input_as_handled()
		elif _pointers.has(event.index):
			if _pointers.size()==1 and not _dragged:_tap(_local(event.position))
			_pointers.erase(event.index);_pinch_distance=0;get_viewport().set_input_as_handled()
	elif event is InputEventScreenDrag and _pointers.has(event.index):
		var local:=_local(event.position)
		if not local.is_finite():return
		var previous:Vector2=_pointers[event.index];_pointers[event.index]=local
		if _pointers.size()>=2 and not _overview:
			var p:Array=_pointers.values();var length:float=p[0].distance_to(p[1]);var angle:float=(p[1]-p[0]).angle()
			if _pinch_distance>1:_pixels_per_ly=clampf(_pixels_per_ly*length/_pinch_distance,4,120);_yaw+=wrapf(angle-_pinch_angle,-PI,PI)
			_pinch_distance=length;_pinch_angle=angle;_dragged=true;queue_redraw()
		else:
			if local.distance_to(_press_origin)>8:_dragged=true
			if _dragged:_pan(local-previous)
		get_viewport().set_input_as_handled()

	elif event is InputEventMouseButton:
		if event.device==-1:return
		if event.button_index in [MOUSE_BUTTON_WHEEL_UP,MOUSE_BUTTON_WHEEL_DOWN] and event.pressed and _inside_plot(event.position):zoom(1 if event.button_index==MOUSE_BUTTON_WHEEL_UP else -1);get_viewport().set_input_as_handled()
		elif event.button_index in [MOUSE_BUTTON_LEFT,MOUSE_BUTTON_RIGHT]:
			if event.pressed:
				if not _inside_plot(event.position):return
				_pointers[-2]=_local(event.position);_press_origin=_pointers[-2];_dragged=false;_mouse_rotating=event.button_index==MOUSE_BUTTON_RIGHT
			elif _pointers.has(-2):
				if not _dragged and not _mouse_rotating:_tap(_local(event.position))
				_pointers.erase(-2);_mouse_rotating=false
			else:return
			get_viewport().set_input_as_handled()
	elif event is InputEventMouseMotion and event.device!=-1 and _pointers.has(-2):
		var local:=_local(event.position)
		if not local.is_finite():return
		var previous:Vector2=_pointers[-2];_pointers[-2]=local
		if local.distance_to(_press_origin)>8:_dragged=true
		if _dragged:
			if _mouse_rotating:_yaw+=(local.x-previous.x)*0.009;_tilt=clampf(_tilt+(local.y-previous.y)*0.006,0.20,1.4);queue_redraw()
			else:_pan(local-previous)
		get_viewport().set_input_as_handled()

func _unhandled_key_input(event:InputEvent)->void:
	if not input_allowed or not is_visible_in_tree() or not event is InputEventKey or not event.pressed:return
	if get_viewport().gui_get_focus_owner() is LineEdit:return
	match event.physical_keycode:
		KEY_C:center_current()
		KEY_EQUAL,KEY_PLUS,KEY_KP_ADD:zoom(1)
		KEY_MINUS,KEY_KP_SUBTRACT:zoom(-1)
		KEY_LEFT:_pan(Vector2(56,0))
		KEY_RIGHT:_pan(Vector2(-56,0))
		KEY_UP:_pan(Vector2(0,56))
		KEY_DOWN:_pan(Vector2(0,-56))
		_:return
	get_viewport().set_input_as_handled()

func _projection(position:Array)->Dictionary:
	var center:Array
	if model.native:center=[(float(_center.x)-float(model.galaxy._sol_q16[0])/65536.0)*8.0,(float(_center.y)-float(model.galaxy._sol_q16[1])/65536.0)*8.0,0.0]
	else:center=[(float(_center.x)-Model.DISPLAY_ORIGIN.x)*8.0,(float(_center.y)-Model.DISPLAY_ORIGIN.y)*8.0,0.0]
	return Model.map_point(position,center,_yaw,_tilt,_pixels_per_ly,_plot.get_center())
func _line(a:Dictionary,b:Dictionary,color:Color,width:=1.0)->void:
	if not a.is_empty() and not b.is_empty():_drawing_canvas.draw_line(a.point,b.point,color,width,true)
func _draw_grid()->void:
	var start_x:=floori(_center.x)-1;var start_y:=floori(_center.y)-1
	var offset_x:=float(model.galaxy._sol_q16[0])/65536.0 if model.native else float(Model.DISPLAY_ORIGIN.x)
	var offset_y:=float(model.galaxy._sol_q16[1])/65536.0 if model.native else float(Model.DISPLAY_ORIGIN.y)
	for i in range(4):
		var x:=float(start_x+i-offset_x)*8.0;var y:=float(start_y+i-offset_y)*8.0
		_line(_projection([x,(start_y-offset_y)*8.0,0.0]),_projection([x,(start_y+3-offset_y)*8.0,0.0]),Color(0.17,0.34,0.49,0.38))
		_line(_projection([(start_x-offset_x)*8.0,y,0.0]),_projection([(start_x+3-offset_x)*8.0,y,0.0]),Color(0.17,0.34,0.49,0.38))
func _draw_range()->void:
	var c:Array=model.current.position_ly;var radius:float=model.jump_range_ly
	if radius<=0:return
	for plane in range(3):
		var previous:Dictionary={}
		for i in range(65):
			var angle:=TAU*float(i)/64;var p:=c.duplicate();p[plane]=float(c[plane])+cos(angle)*radius;p[(plane+1)%3]=float(c[(plane+1)%3])+sin(angle)*radius
			var point:=_projection(p)
			if not previous.is_empty():_line(previous,point,Color(0.19,0.61,0.73,0.16))
			previous=point
func _draw_star(point:Vector2,color:Color,important:bool,selected:bool)->void:
	# Three inexpensive translucent halos, always centred on a real source star.
	for layer in range(3,0,-1):
		var glow:=color;glow.a=0.035 if layer==3 else (0.07 if layer==2 else 0.14)
		_drawing_canvas.draw_circle(point,float(layer)*(5.0 if important else 3.0),glow,true,-1,true)
	_drawing_canvas.draw_circle(point,4.0 if important else 2.3,color,true,-1,true)
	_drawing_canvas.draw_circle(point,1.3,Color("eef9ff"),true,-1,true)
	if selected:
		_drawing_canvas.draw_arc(point,11,0,TAU,36,color,1.4,true)
		for direction in [Vector2.LEFT,Vector2.RIGHT,Vector2.UP,Vector2.DOWN]:_drawing_canvas.draw_line(point+direction*15,point+direction*19,color,1.2,true)
	elif important:_drawing_canvas.draw_arc(point,9,0,TAU,32,Color(color,0.65),1,true)
func _draw_sector()->void:
	_markers.clear();last_label_rects.clear();_draw_grid();_draw_range()
	var current:=_projection(model.current.position_ly);var selected:=_projection(model.selected.position_ly)
	_line(current,selected,Color(0.24,0.77,0.88,0.1),9)
	_line(current,selected,Color(0.24,0.77,0.88,0.23),4)
	_line(current,selected,Color("8be6ed"),1.5)
	var font:=ThemeDB.fallback_font
	var priority:Array[Dictionary]=[]
	var minor:Array[Dictionary]=[]
	for row:Dictionary in model.rows:
		var top:=_projection(row.position_ly)
		if top.is_empty() or not _plot.has_point(top.point):continue
		var ground:Array=row.position_ly.duplicate();ground[2]=0.0;var base:=_projection(ground)
		_line(base,top,Color(0.26,0.5,0.66,0.35))
		var id:=int(row.id);var color:=Color("b4d6f0")
		if id==model.current_id:color=Color("79e6b7")
		elif id==model.selected_id:color=Color("f3d597")
		_draw_star(top.point,color,id in [model.current_id,model.selected_id],id==model.selected_id)
		_markers.append({"id":id,"point":top.point})
		var label:={"id":id,"point":top.point,"name":str(row.name),"color":color}
		if id==model.current_id:priority.push_front(label)
		elif id==model.selected_id:priority.append(label)
		elif model.rows.size()<90:minor.append(label)
	priority.append_array(minor)
	for label:Dictionary in priority:
		var width:=ceilf(font.get_string_size(label.name,HORIZONTAL_ALIGNMENT_LEFT,-1,14).x)
		var height:=ceilf(font.get_height(14))
		var point:Vector2=label.point
		# Bounded placement around each real marker; source positions, marker hit
		# regions and font size stay unchanged. Clip the complete text rectangle.
		var offsets:=[Vector2(7,-height-4),Vector2(7,5),Vector2(-width-7,-height-4),Vector2(-width-7,5),Vector2(-width*0.5,-height-12),Vector2(-width*0.5,12),Vector2(7,-height*2-6),Vector2(7,height+8)]
		for offset:Vector2 in offsets:
			var rect:=Rect2((point+offset).round(),Vector2(width,height)).grow(2)
			if not _plot.encloses(rect):continue
			var occupied:=false
			for previous:Dictionary in last_label_rects:
				if rect.intersects(previous.rect):occupied=true;break
			if occupied:continue
			last_label_rects.append({"id":label.id,"rect":rect,"marker":point})
			_drawing_canvas.draw_string(font,rect.position+Vector2(2,2+font.get_ascent(14)),label.name,HORIZONTAL_ALIGNMENT_LEFT,-1,14,label.color)
			break
func _draw_overview()->void:
	last_label_rects.clear()
	var fit:=minf(_plot.size.x/320.0,_plot.size.y/158.0)
	_overview_rect=Rect2(_plot.get_center()-Vector2(320,158)*fit*0.5,Vector2(320,158)*fit)
	if _overview_texture!=null:_drawing_canvas.draw_texture_rect(_overview_texture,_overview_rect,false)
	for fraction in [0.25,0.5,0.75]:
		var x:float=_overview_rect.position.x+_overview_rect.size.x*fraction;var y:float=_overview_rect.position.y+_overview_rect.size.y*fraction
		_drawing_canvas.draw_dashed_line(Vector2(x,_overview_rect.position.y),Vector2(x,_overview_rect.end.y),Color(0.3,0.65,0.8,0.12),1,5,true)
		_drawing_canvas.draw_dashed_line(Vector2(_overview_rect.position.x,y),Vector2(_overview_rect.end.x,y),Color(0.3,0.65,0.8,0.12),1,5,true)
	_drawing_canvas.draw_arc(_overview_rect.get_center(),8,0,TAU,32,Color(0.42,0.75,0.85,0.5),1,true)
	var current:Vector2=model.sector_position(model.current)
	var sx:=floori(_center.x)-(_overview_scale>>1)+160*_overview_scale;var sy:=floori(_center.y)+(_overview_scale>>1)-79*_overview_scale
	var p:=Vector2(319-(float(sx)-current.x)/_overview_scale,157-(current.y-float(sy))/_overview_scale)
	var marker:=_overview_rect.position+p/Vector2(320,158)*_overview_rect.size
	if _overview_rect.has_point(marker):
		_draw_star(marker,Color("79e6b7"),true,false)
		_drawing_canvas.draw_string(ThemeDB.fallback_font,marker+Vector2(13,-8),str(model.current.name),HORIZONTAL_ALIGNMENT_LEFT,170,15,Color("b0f4d1"))
	for landmark:Dictionary in model._map_data.get("landmarks",[]):
		# F846 stops once its descending maximum-scale threshold is below the
		# current scale. Unknown text codes are not replaced with invented names.
		if int(landmark.get("visible_above_scale",0))<_overview_scale:continue
		if not landmark.get("name_ru") is String:continue
		var raw:Array=landmark.get("sector_raw",[])
		if raw.size()!=2:continue
		var pixel:=Vector2(319-(float(sx)-float(raw[0]))/_overview_scale,157-(float(raw[1])-float(sy))/_overview_scale)
		var where:=_overview_rect.position+pixel/Vector2(320,158)*_overview_rect.size
		if _overview_rect.has_point(where):_drawing_canvas.draw_string(ThemeDB.fallback_font,where,str(landmark.name_ru),HORIZONTAL_ALIGNMENT_LEFT,210,14,Color("8cbdcf"))
func _paint_plot(canvas:Control)->void:
	if model==null:return
	_drawing_canvas=canvas;canvas.draw_set_transform(-_plot.position)
	if _overview:_draw_overview()
	else:_draw_sector()
func _draw()->void:
	draw_rect(Rect2(Vector2.ZERO,size),Color("050b16"))
	# Low-cost ambient washes, without decorative stars or navigation geometry.
	for band in range(16):
		var t:=float(band)/15.0
		draw_rect(Rect2(0,size.y*t,size.x,size.y/15.0+1),Color("0a1a2d").lerp(Color("050b16"),t))
	if _chart_style==null:return
	draw_style_box(_chart_style,_plot.grow(1))
	draw_style_box(_card_style,_selection_card)
	draw_style_box(_toolbar_style,Rect2(12,size.y-158,size.x-24,150))
	draw_line(Vector2(22,64),Vector2(size.x-146,64),Color("183044"),1,true)
	var separator_y:=215.0 if size.y<COMPACT_CARD_HEIGHT else 299.0
	draw_line(Vector2(_selection_card.position.x+18,separator_y),Vector2(_selection_card.end.x-18,separator_y),Color("1c3c51"),1,true)
	var font:=ThemeDB.fallback_font
	var legend_y:float=_plot.position.y-17.0
	var legends:=[{"x":30.0,"name":"Корабль","color":Color("79e6b7")},{"x":142.0,"name":"Выбор","color":Color("f3d597")},{"x":238.0,"name":"Радиус прыжка","color":Color("5ba6bc")}]
	for item:Dictionary in legends:
		draw_circle(Vector2(item.x,legend_y),2.6,item.color,true,-1,true)
		draw_string(font,Vector2(item.x+10,legend_y+4),item.name,HORIZONTAL_ALIGNMENT_LEFT,-1,12,Color("8faebf"))
	for corner in [_plot.position,_plot.position+Vector2(_plot.size.x,0),_plot.end,_plot.position+Vector2(0,_plot.size.y)]:
		var dx:=1.0 if corner.x<_plot.get_center().x else -1.0;var dy:=1.0 if corner.y<_plot.get_center().y else -1.0
		draw_line(corner+Vector2(dx*3,0),corner+Vector2(dx*24,0),Color("4d97b2"),1.5,true)
		draw_line(corner+Vector2(0,dy*3),corner+Vector2(0,dy*20),Color("4d97b2"),1.5,true)
	if _plot_canvas!=null:_plot_canvas.queue_redraw()

scripts/source_jet_fuel.gd.source:
extends RefCounted
# Uploaded DOS F938 fuel tail, F929 depletion/automatic feeder and F289 manual
# refuelling. The other F938 shield/hull/cooldown transitions are not applied.
# Every operation returns an independent state; callbacks are observations,
# never invocations of the original GUI or another gameplay model.
const DATA_PATH:="res://data/ffe_fuel.json"
const SOURCE_SHA:="d919566140abfc298bc9929bc9141d92526586821f017be1336253a04bca1e72"
const CONTRACT:="dos-firstenc-f929-f938-tail-f289-jet-v1"
const SOURCE_POLICY:="uploaded-dos-f929-three-positive-limits-no-automatic-restore"
const MASK:=0xffffffff
const RAW_PER_TONNE:=0x20000000
const MANUAL_NEAR_FULL_MARGIN:=0x01999999
const TICKS_PER_UPDATE_SECOND:=0xc22e
const STATE_KEYS:=["jet_raw_u32","object_index_u8","drive_index_s8","npc_fuel_u8","auto_refueller","thrust_u16","cached_thrust_u16","player_object_index_u32","status_u16","cargo_s32","hydrogen_u16","military_u16","waste_u16"]
static var _tables:Dictionary={}
static var _mutex:=Mutex.new()

static func _number(value:Variant,low:int,high:int)->bool:
	return (value is int or value is float) and is_finite(float(value)) and float(value)==floorf(float(value)) and value>=low and value<=high
static func _s32(value:int)->int:
	value&=MASK;return value-0x100000000 if value>=0x80000000 else value
static func _hex(value:Variant)->bool:
	if not value is String or value.length()%2!=0:return false
	for character:String in value:
		if not character in "0123456789abcdefABCDEF":return false
	return true
static func _load()->bool:
	_mutex.lock()
	if not _tables.is_empty():_mutex.unlock();return true
	var data:Variant=JSON.parse_string(FileAccess.get_file_as_string(DATA_PATH)) if FileAccess.file_exists(DATA_PATH) else null
	if not data is Dictionary or data.get("schema")!=1 or data.get("source_sha256")!=SOURCE_SHA or not data.get("tables_hex") is Dictionary:_mutex.unlock();return false
	var candidate:Dictionary={}
	for key:String in ["5111","6266"]:
		var raw:Variant=data.tables_hex.get(key)
		if not _hex(raw) or raw.length()!=120:_mutex.unlock();return false
		candidate[key]=str(raw).hex_decode()
	_tables=candidate;_mutex.unlock();return true
static func jet_capacity_raw(drive_index:int)->int:
	if drive_index<0 or drive_index>=15 or not _load():return -1
	return int(_tables["5111"].decode_u32(drive_index*4))
static func npc_initial_jet_raw(drive_index:int)->int:
	# Exact isolated F773 DATA6266 lookup/SHL24; not a player-starter policy.
	if drive_index<0 or drive_index>=15 or not _load():return -1
	return (int(_tables["6266"].decode_u32(drive_index*4))<<24)&MASK

static func valid_state(state:Dictionary)->bool:
	for key:String in STATE_KEYS:
		if not state.has(key):return false
	for key:String in ["jet_raw_u32","player_object_index_u32"]:
		if not _number(state[key],0,MASK):return false
	for key:String in ["object_index_u8","npc_fuel_u8"]:
		if not _number(state[key],0,255):return false
	if not _number(state.drive_index_s8,-128,127) or not state.auto_refueller is bool or not _number(state.cargo_s32,-2147483648,2147483647):return false
	for key:String in ["status_u16","hydrogen_u16","military_u16","waste_u16"]:
		if not _number(state[key],0,65535):return false
	for key:String in ["thrust_u16","cached_thrust_u16"]:
		if not state[key] is Array or state[key].size()!=6:return false
		for value:Variant in state[key]:
			if not _number(value,0,65535):return false
	return true
static func _rejected(state:Dictionary,reason:String)->Dictionary:
	return {"ok":false,"accepted":false,"changed":false,"state":state.duplicate(true),"reason":reason,"events":[],"callbacks":[],"source_contract":CONTRACT,"source_sha256":SOURCE_SHA}
static func _result(original:Dictionary,state:Dictionary,reason:String,events:Array=[],callbacks:Array=[],accepted:=true,refilled:=false)->Dictionary:
	var available:=false;var disabled:=0
	for index in range(6):
		if int(state.thrust_u16[index])!=0:available=true
		elif int(state.cached_thrust_u16[index])!=0:disabled|=1<<index
	return {"ok":true,"accepted":accepted,"changed":state!=original,"state":state,"reason":reason,"events":events,"callbacks":callbacks,"refilled":refilled,"propulsion_available":available,"disabled_axes_mask_u8":disabled,"source_policy":SOURCE_POLICY,"source_contract":CONTRACT,"source_sha256":SOURCE_SHA}

static func consumption(mass_s16:int,commands_s16:Array,step_s32:int)->Dictionary:
	if not _number(mass_s16,-32768,32767) or not _number(step_s32,-2147483648,2147483647) or commands_s16.size()!=3:return {"ok":false,"amount_u32":0,"reason":"invalid_source_domain"}
	var magnitude:=0
	for value:Variant in commands_s16:
		if not _number(value,-32768,32767):return {"ok":false,"amount_u32":0,"reason":"invalid_source_domain"}
		# MOVSX/NEG is a32-bit operation; -32768 therefore becomes+32768.
		magnitude+=absi(int(value))
	var amount:=_s32(mass_s16*magnitude)>>9
	amount=_s32(amount*step_s32)
	return {"ok":true,"amount_u32":amount&MASK,"amount_s32":amount,"command_magnitude":magnitude,"source_procedure":"F938 fuel tail","step_units":"F152/F151 whole display seconds, each49710 master ticks; player F1007 and NPC F707/F706/F732 share this event quantum"}

static func cadence(current_tick_u32:int,last_processed_tick_u32:int)->Dictionary:
	if not _number(current_tick_u32,0,MASK) or not _number(last_processed_tick_u32,0,MASK):return {"ok":false,"reason":"invalid_source_clock"}
	var delta:=(current_tick_u32-last_processed_tick_u32)&MASK
	@warning_ignore("integer_division")
	var seconds:int=delta/TICKS_PER_UPDATE_SECOND
	return {"ok":true,"whole_seconds":seconds,"last_processed_tick_u32":(last_processed_tick_u32+seconds*TICKS_PER_UPDATE_SECOND)&MASK,"delta_u32":delta,"remainder_ticks":delta%TICKS_PER_UPDATE_SECOND,"source_procedure":"F152 display-second event boundary"}

static func cooling(heat_s32:int,step_s32:int,shielding:bool=false)->Dictionary:
	if not _number(heat_s32,-2147483648,2147483647) or not _number(step_s32,-2147483648,2147483647):return {"ok":false,"reason":"invalid_source_domain"}
	# F1007's initial signed32 heat field. Zero skips cooling altogether;
	# subtraction and the source negative clamp happen after32-bit truncation.
	var result:=heat_s32
	if heat_s32!=0:result=maxi(0,_s32(heat_s32-_s32(step_s32<<(9 if shielding else 7))))
	return {"ok":true,"heat_s32":result,"source_procedure":"F1007 thermal head only","source_step_units":"whole display seconds from F152/F151"}

static func consume(input:Dictionary,amount_u32:int)->Dictionary:
	if not valid_state(input):return _rejected(input,"invalid_state")
	if not _number(amount_u32,0,MASK):return _rejected(input,"invalid_amount")
	var state:=input.duplicate(true);var player:=int(state.object_index_u8)==int(state.player_object_index_u32)
	if int(state.jet_raw_u32)>amount_u32:
		state.jet_raw_u32=(int(state.jet_raw_u32)-amount_u32)&MASK
		# DOS has a direct jump to return here. The later JJFFE cached-six-axis
		# restoration is a verified separate patch, not the reference behavior.
		return _result(input,state,"spent")
	# Exact F929 JNA includes equality and empty+zero demand. Unspent debit
	# beyond the old tank is not carried into the newly transferred tonne.
	state.jet_raw_u32=0
	if player and state.auto_refueller:
		if int(state.drive_index_s8)<10 and int(state.hydrogen_u16)!=0:
			state.hydrogen_u16=(int(state.hydrogen_u16)-1)&65535
			state.cargo_s32=_s32(int(state.cargo_s32)-1);state.jet_raw_u32=RAW_PER_TONNE
			return _result(input,state,"auto_hydrogen",[],[],true,true)
		if int(state.drive_index_s8)>=10 and int(state.military_u16)!=0:
			state.military_u16=(int(state.military_u16)-1)&65535
			state.waste_u16=(int(state.waste_u16)+1)&65535;state.jet_raw_u32=RAW_PER_TONNE
			return _result(input,state,"auto_military",[],[],true,true)
	elif not player and int(state.npc_fuel_u8)!=0:
		state.npc_fuel_u8=(int(state.npc_fuel_u8)-1)&255;state.jet_raw_u32=RAW_PER_TONNE
		return _result(input,state,"npc_refill",[],[],true,true)
	var events:Array=[]
	if player and (int(state.status_u16)&1)==0:
		state.status_u16=int(state.status_u16)|1;events.append(0x9907)
	# Actual DOS clears only the BC/C0/C4 positive-direction words. Preserve
	# the reverse-direction words; JJFFE additionally clears BE/C2/C6.
	for index in [0,2,4]:state.thrust_u16[index]=0
	return _result(input,state,"empty",events,[],false)

static func fuel_step(input:Dictionary,mass_s16:int,commands_s16:Array,step_s32:int)->Dictionary:
	var demand:=consumption(mass_s16,commands_s16,step_s32)
	if not demand.ok:return _rejected(input,"invalid_source_domain")
	var result:=consume(input,int(demand.amount_u32));result["consumption"]=demand
	return result

static func manual_refuel(input:Dictionary,capacity_raw_u32:int)->Dictionary:
	if not valid_state(input):return _rejected(input,"invalid_state")
	var drive_index:=int(input.drive_index_s8)&255
	if drive_index>=15 or not _number(capacity_raw_u32,0,MASK):return _rejected(input,"invalid_capacity_domain")
	var state:=input.duplicate(true);var previous:=int(state.jet_raw_u32)
	if previous>=((capacity_raw_u32-MANUAL_NEAR_FULL_MARGIN)&MASK):return _result(input,state,"near_full",[0x99e3],[287],false)
	# F289's drive test is UNSIGNED, unlike F929's signed byte comparison.
	if drive_index<10:
		if int(state.hydrogen_u16)==0:return _result(input,state,"no_fuel",[],[293],false)
		state.hydrogen_u16=(int(state.hydrogen_u16)-1)&65535;state.cargo_s32=_s32(int(state.cargo_s32)-1)
	else:
		if int(state.military_u16)==0:return _result(input,state,"no_fuel",[],[293],false)
		state.military_u16=(int(state.military_u16)-1)&65535;state.waste_u16=(int(state.waste_u16)+1)&65535
	state.status_u16=int(state.status_u16)&0xfffe;state.thrust_u16=state.cached_thrust_u16.duplicate()
	var after:=(previous+RAW_PER_TONNE)&MASK;var events:Array=[]
	if after>capacity_raw_u32 or after<=previous:after=capacity_raw_u32;events.append(0x99e3)
	state.jet_raw_u32=after
	return _result(input,state,"manual_refuel",events,[287],true,true)

scripts/source_fuel_scoop.gd.source:
extends RefCounted
# Original F1033/F1034 after the caller supplies an actual F569 result.
# Geometry, SI conversion, timer scheduling and the F953 destruction callback
# belong to the caller. This kernel neither invents an atmosphere nor fills
# the separate reaction tank. Every caller-owned buffer is copied.
const CONTRACT:="jjffe-f1033-after-f569-fuel-scoop-v1"
const ASM_SHA:="d4f1b76aa78895d3634b182428e14f36ac57b304e56fedb67a89ee39b5f6873a"
const GAME_BYTES:=544
const OBJECT_BYTES:=338
const MASK:=0xffffffff
const HYDROGEN_COMMODITY_INDEX:=19
const SCOOP_EQUIPMENT_CA_MASK:=0x10
const ALTITUDE_LIMIT_RAW:=30000000
const SPEED_MINIMUM_RAW:=9000
const COOLDOWN_RESET_RAW:=149130

static func _integer(value:Variant,low:int,high:int)->bool:
	return (value is int or value is float) and is_finite(float(value)) and float(value)==floorf(float(value)) and value>=low and value<=high
static func _s32(value:int)->int:
	value&=MASK;return value-0x100000000 if value>=0x80000000 else value
static func _s8(value:int)->int:
	value&=255;return value-256 if value>=128 else value
static func _rejected(reason:String,game:PackedByteArray,object:PackedByteArray)->Dictionary:
	return {"ok":false,"reason":reason,"source_contract":CONTRACT,"game":game.duplicate(),"object":object.duplicate()}

static func evaluate_buffers(game_bytes:PackedByteArray,object_bytes:PackedByteArray,contact:Dictionary,step_u32:Variant,sound_mode_s8:Variant=0)->Dictionary:
	if game_bytes.size()!=GAME_BYTES or object_bytes.size()!=OBJECT_BYTES:return _rejected("invalid_buffers",game_bytes,object_bytes)
	if not _integer(step_u32,0,MASK) or not _integer(sound_mode_s8,-128,127):return _rejected("invalid_step_or_sound_mode",game_bytes,object_bytes)
	if not _integer(contact.get("flags_u8"),0,255) or not _integer(contact.get("altitude_raw_s32"),-2147483648,2147483647) or not _integer(contact.get("parent_model_u32"),0,MASK):return _rejected("invalid_contact",game_bytes,object_bytes)
	var game:=game_bytes.duplicate();var object:=object_bytes.duplicate()
	var flags:=int(contact.flags_u8);var altitude:=int(contact.altitude_raw_s32);var model:=int(contact.parent_model_u32)
	var events:={"refresh":0,"notify":0,"sound":0,"destroy":0,"message_code":0,"message_amount":0,"notify_first":0,"notify_second":0}
	game[0x212]=flags;game.encode_u32(0xdc,(0x7fffffff if altitude==-1 else altitude)&MASK)
	var hud_altitude:=_s32(game.decode_u32(0xdc));var control_flags:=int(game.decode_u16(0xc6))
	if hud_altitude>=12000000:
		if int(game[0xe8])!=0x2c:
			if control_flags&0x40!=0 and int(sound_mode_s8)<0:events.refresh+=1
			control_flags|=0x40;game.encode_u16(0xc6,control_flags)
	else:
		if control_flags&0x40!=0 and int(sound_mode_s8)<0:events.refresh+=1
		control_flags&=0xffbf;game.encode_u16(0xc6,control_flags)
	var reason:="outside_atmosphere"
	if flags&1==0:
		# F1034: without the cargo life-support mask, livestock/slaves spoil
		# into their two source goods. This does not alter total cargo mass.
		if int(object[0xca])&2==0:
			for pair:Array in [[0x14c,0x146],[0x14a,0x13c]]:
				if game.decode_u16(pair[0])!=0:
					game.encode_u16(pair[0],(int(game.decode_u16(pair[0]))-1)&65535)
					game.encode_u16(pair[1],(int(game.decode_u16(pair[1]))+1)&65535)
	elif model<134 or model>148:reason="ineligible_parent_model"
	else:
		var eligible:=true
		if int(object[0xca])&SCOOP_EQUIPMENT_CA_MASK!=0:
			if altitude>ALTITUDE_LIMIT_RAW:reason="too_high";eligible=false
			elif _s32(game.decode_u32(0xd8))<SPEED_MINIMUM_RAW:reason="too_slow";eligible=false
			elif int(game.decode_u32(0x1e8))>int(step_u32):reason="cooldown";eligible=false
			else:
				if _s32(game.decode_u32(0x120))<_s32(game.decode_u32(0x118)):
					game.encode_u32(0x120,(_s32(game.decode_u32(0x120))+1)&MASK)
