		var offset:int={"cargo_used_s32":0x120,"capacity_s32":0x118,"cooldown_u32":0x1e8,"heat_s32":0x1ec,"speed_s32":0xd8}[key];game.encode_u32(offset,int(values[key])&MASK)
	game.encode_u16(0x15a,values.hydrogen_u16)
